#!/usr/bin/env python3
"""Build script for INJ-09-2026-W3-AECN (AECN rail weekly removal) QA checklist."""
import json
import math
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3] / "skills/qa/batch-qa-aecn/scripts"))
import openpyxl
from openpyxl.styles import Font, PatternFill, Alignment
from checklist_lib import build_with_validation

HERE = Path(__file__).parent
SOURCE_READS = HERE / "batch_INJ-09-2026-W3-AECN_source_reads.json"
OUT = HERE / "Batch_INJ-09-2026-W3-AECN_QA_Checklist.xlsx"
L = json.load(open(SOURCE_READS))

comp = L["certify"]["components"]
def cv(n):
    c = comp[n]
    return c["value"] / (1000 if c["unit"].startswith("kg") else 1)
PP, PE = "AECN pyrolysis (from rail loads) - process emissions", "AECN pyrolysis (from rail loads) - embodied emissions"
TP = ["AECN to SOPOR Tanker Truck Transport Process Emissions", "SOPOR to Opelousas Rail Transport Process Emissions", "Opelousas to Basco - Tanker Truck Transport Process Emissions"]
TE = ["AECN to SOPOR Tanker Truck Transport Embodied Emissions", "SOPOR to Opelousas Rail Transport Embodied Emissions", "Opelousas to Basco Tanker Truck Transport Embodied Emissions"]
roll = L["ops_notes"]["rollup"]
MOBI = roll["mobi_kg"]["value"]
MOI = comp["Injection sequestration"]["inputs"]["product_mass"]["value"] * 1000
C = L["lab_results"]["carbon_pct"] / 100
SEQ = cv("Injection sequestration")
G_INT = MOBI / 1000 * C * 3.667
PROC = sum(cv(n) for n in TP)
EMB = sum(cv(n) for n in TE)
PYRO = cv(PP) + cv(PE)
ACTS = PYRO + PROC + EMB
BCU = cv("BCU - Transport Process")
DISC = L["certify"]["uncertainty_discount_t"]
NET_INT = G_INT + min(BCU, PROC) - L["certify"]["activities_t"] - DISC
SD_M = comp["Injection sequestration"]["inputs"]["product_mass"]["sd"] * 1000
SD_C = comp["Injection sequestration"]["inputs"]["carbon_content"]["sd"]
MASS_ACTS = cv(PP) + cv(PE) + PROC
DISC_A = math.sqrt((G_INT * math.sqrt((SD_M / MOBI) ** 2 + (SD_C / 39.7) ** 2)) ** 2 + (MASS_ACTS * SD_M / (roll["mass_used_kg"]["value"])) ** 2)
M = roll["mass_used_kg"]["value"] / 1000
EFS = L["standard_efs"]
SHEET_PROC = [M * inp["distance"]["value"] * ef for inp, ef in ((comp[TP[0]]["inputs"], EFS["row6_tanker_fuel"]["final_F"]), (comp[TP[1]]["inputs"], EFS["row10_rail_fuel"]["final_F"]), (comp[TP[2]]["inputs"], EFS["row6_tanker_fuel"]["final_F"]))]
SHEET_EMB = [roll["aecn_sopor_alloc_mi_sum"]["value"] * EFS["row11_tanker_embodied"]["final_F"], roll["rail_alloc_mi_sum"]["value"] * EFS["row13_railcar_embodied"]["final_F"], roll["opel_basco_mi_sum"]["value"] * EFS["row11_tanker_embodied"]["final_F"]]
offs = L["scale_tickets"]["offloads"]
nets = [o["computed_net_lb"] for o in offs.values()]
fulls = [o["full_ticket"]["gross_weight_lb"] for o in offs.values()]
steers = [o["full_ticket"]["steer_lb"] for o in offs.values() if o["full_ticket"]["steer_lb"]]
dens = [b["density_g_ml_60F"] for b in L["bols"]["per_bol"].values()]
cr = L["carbon_range"]
Z = (L["lab_results"]["carbon_pct"] - cr["mean_C_pct"]) / cr["sd_C_pct"]
cars = {r["railcar"]: r for r in L["ops_notes"]["railcars"]}
for o in offs.values():   # every empty weigh follows its full weigh
    assert (o["empty_ticket"]["date"], o["empty_ticket"]["time"]) > (o["full_ticket"]["date"], o["full_ticket"]["time"])

DERIVED = {
    "moi_delta_calc": f"{MOI:.5f} - {MOBI} = {MOI - MOBI:.5f} kg; K46 = 200 x 3.785411784 x 1.192 = {roll['mass_removed_rnd_kg']['value']} kg",
    "gross_internal_calc": f"{MOBI / 1000:.7f} t x {C} x 3.667 = {G_INT:.6f} t; Certify {MOI / 1000:.8f} t x {C} x 3.667 = {SEQ:.6f} t; overstated {SEQ - G_INT:.6f} t",
    "activities_calc": f"{cv(PP):.6f} + {cv(PE):.6f} = {PYRO:.6f}; " + " + ".join(f"{cv(n):.6f}" for n in TP) + f" = {PROC:.6f}; " + " + ".join(f"{cv(n):.6f}" for n in TE) + f" = {EMB:.6f}; {PROC:.6f} + {EMB:.6f} = {PROC + EMB:.6f}; {PYRO:.6f} + {PROC + EMB:.6f} = {ACTS:.6f}",
    "transport_calc": "sheet EFs: process " + ", ".join(f"{x:.6f}" for x in SHEET_PROC) + f" (sum {sum(SHEET_PROC):.6f}); embodied " + ", ".join(f"{x:.6f}" for x in SHEET_EMB) + "; Certify process " + ", ".join(f"{cv(n):.6f}" for n in TP) + "; Certify embodied " + ", ".join(f"{cv(n):.6f}" for n in TE),
    "discount_pct_calc": f"{DISC:.10f} / {SEQ:.6f} = {DISC / SEQ:.5f} ({DISC / SEQ * 100:.2f} %)",
    "carbon_z_calc": f"(39.7 - {cr['mean_C_pct']}) / {cr['sd_C_pct']} = {Z:.3f} SD; band {cr['lower_2sd']:.2f} to {cr['upper_2sd']:.2f} %",
    "unc_calc": "10 x 72.57 = 725.7 kg; 0.004 x 39.7 = 0.1588 %",
    "ticket_ranges_calc": f"nets {min(nets)} to {max(nets)} lb; full gross {min(fulls)} to {max(fulls)} lb; non-zero full-ticket steer {min(steers)} to {max(steers)} lb",
    "loss_calc": f"GPRX5102 {cars['GPRX5102']['loss_kg']['value']} / 77940 = {cars['GPRX5102']['loss_kg']['value'] / 77940 * 100:.3f} %; TILX200231 {cars['TILX200231']['loss_kg']['value']} / 77520 = {cars['TILX200231']['loss_kg']['value'] / 77520 * 100:.3f} %",
    "bol_density_range_calc": f"BOL density at 60F across 9 BOLs {min(dens)} to {max(dens)} g/mL; SGS 1.192; vendor LCA 1.1997; guidance 1.22",
    "bcu_calc": f"{BCU} - {PROC:.9f} = {BCU - PROC:.9f} t; {BCU} - {sum(SHEET_PROC):.9f} = {BCU - sum(SHEET_PROC):.9f} t",
    "net_internal_calc": f"{G_INT:.6f} + {min(BCU, PROC):.6f} - {ACTS:.6f} - {DISC_A:.6f} (discount re-derived on the corrected mass) = {G_INT + min(BCU, PROC) - ACTS - DISC_A:.6f} t vs 249.637; delta {G_INT + min(BCU, PROC) - ACTS - DISC_A - 249.637:.6f} t",
    "guidance_basis_loss_calc": f"GPRX5102 79298.78 - {cars['GPRX5102']['total_offloaded_kg']['value']} = {79298.78 - cars['GPRX5102']['total_offloaded_kg']['value']:.2f} kg; TILX200231 79030.38 - {cars['TILX200231']['total_offloaded_kg']['value']} = {79030.38 - cars['TILX200231']['total_offloaded_kg']['value']:.2f} kg",
    "loss_upstream_calc": (lambda lt: f"{cars['GPRX5102']['loss_kg']['value']} + {cars['TILX200231']['loss_kg']['value']} = {lt:.5f} kg; pyrolysis {lt/1000:.8f} x (0.13712 + 0.02116) = {lt/1000*0.15828:.6f} t; truck {lt/1000:.8f} x 107.49722 x 0.0001143 = {lt/1000*107.49722*0.0001143:.6f} t; rail {lt/1000:.8f} x 2199 x 0.00002591 = {lt/1000*2199*0.00002591:.6f} t; total {lt/1000*(0.15828+107.49722*0.0001143+2199*0.00002591):.6f} t")(cars['GPRX5102']['loss_kg']['value'] + cars['TILX200231']['loss_kg']['value']),
    "eac_calc": f"2795 - {L['bcu_sources']['inventory_row16']['H_total_reduction_MT']} = {2795 - L['bcu_sources']['inventory_row16']['H_total_reduction_MT']:.6f} t",
}

