def _height(text, width_chars):
    return 15 * max(1, math.ceil(len(text or "") / width_chars))


def build_workbook(rows):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "QA Checklist"
    for col, w in zip("ABCDE", (8, 60, 10, 95, 30)):
        ws.column_dimensions[col].width = w
    r = 1
    for row in rows:
        kind = row[0]
        if kind in ("HEADER", "SECTION"):
            c = ws.cell(row=r, column=1, value=row[1])
            c.font = Font(bold=True)
            c.alignment = Alignment(wrap_text=True, vertical="top")
            if kind == "SECTION":
                # not merged: openpyxl drops the fill on merged-over cells when saving
                c.alignment = Alignment(wrap_text=False, vertical="top")
                for col in range(1, 6):
                    ws.cell(row=r, column=col).fill = HDR_FILL
            else:
                ws.merge_cells(start_row=r, start_column=1, end_row=r, end_column=5)
            ws.row_dimensions[r].height = max(15 * math.ceil(len(row[1]) / 200), _height(row[1], 190))
            r += 1
            continue
        item, check, status, evidence, verifier = row
        for col, val in enumerate((item, check, status, evidence, verifier), start=1):
            c = ws.cell(row=r, column=col, value=val)
            c.alignment = Alignment(wrap_text=True, vertical="top")
        if status == "Fail":
            for col in range(1, 6):
                ws.cell(row=r, column=col).fill = FAIL_FILL
        elif status == "Flag":
            for col in range(1, 6):
                ws.cell(row=r, column=col).fill = FLAG_FILL
                ws.cell(row=r, column=col).font = Font(color="996600")
        elif status == "N/A":
            for col in range(1, 6):
                ws.cell(row=r, column=col).font = NA_FONT
        ws.row_dimensions[r].height = max(_height(evidence, 88), _height(check, 55))
        r += 1
    ws.freeze_panes = "A2"
    ws.page_setup.orientation = "landscape"
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.print_title_rows = "1:1"
    return wb


if __name__ == "__main__":
    build_with_validation(rows=ROWS, source_reads_path=SOURCE_READS, out_path=OUT, build_workbook_fn=build_workbook, derived_values=DERIVED)
    print("built", OUT)
